import axios from "axios"
import React, { useState, useEffect } from "react"
import { useLocation, Link } from 'react-router-dom'


const MemberInfo = () => {
    const [member, setMember] = useState()

    const location = useLocation()

    const memberId = location.pathname.split("/")[2] // gets the member id

    useEffect(() => {
        const fetchMember = async () => {
            try {
                const res = await axios.get(`http://localhost:8800/member/${memberId}`)
                setMember(res.data)
            } catch (err) {
                console.log(err)
            }
        }
        fetchMember()
    }, [])

    console.log(member)

    const handleClick = async (event) => {
        event.preventDefault()

        try {
            await axios.put(`http://localhost:8800/member/${memberId}`)
        } catch {

        }
    }

    return (
        <div>
            <h1>Information</h1>
            <div className="form">
                <input 
                type="text" 
                onChange={handleChange} 
                placeholder="firstname" 
                name="firstname" 
                />
                <input 
                type="text" 
                onChange={handleChange} 
                placeholder="lastname" 
                name="lastname" 
                />
                <input 
                type="text" 
                onChange={handleChange} 
                placeholder="membership" 
                name="membership" 
                />
                <input 
                type="text" 
                onChange={handleChange} 
                placeholder="age" 
                name="age" 
                />
                <button className="formButton" onClick={handleClick}>Update</button>

                <button className="">
                    <Link to="/home" style={{ color: "inherit", textDecoration: "none" }}>Home</Link>
                </button>
            </div>
        </div>
    )
}

export default MemberInfo
